package com.jobpilot.config;import com.jobpilot.user.UserRepository;import org.springframework.context.annotation.*;import org.springframework.security.core.userdetails.*;@Configuration public class UserDetailsConfig{@Bean UserDetailsService userDetailsService(UserRepository users){return email->users.findByEmail(email).map(u->User.withUsername(u.getEmail()).password(u.getPassword()).authorities("USER").build()).orElseThrow(()->new UsernameNotFoundException(email));}}
